#!/usr/bin/env python3
"""Spring quarter 2025 shipped-order reconciliation against the local order service.

Read-only. Writes /workspace/result.json only after the final checks pass.
"""
import email.utils
import json
import time
import urllib.error
import urllib.request
from collections import Counter
from datetime import datetime, timezone
from pathlib import Path

BASE = "http://localhost:8080"
WORKDIR = Path("/tmp/recon")
RAW_DIR = WORKDIR / "raw"
LOG_PATH = WORKDIR / "run.log"
RESULT_PATH = Path("/workspace/result.json")

# 1 March 00:00 UTC up to, but not including, 1 June 00:00 UTC: 1 March to 31 May inclusive.
WINDOW_START = datetime(2025, 3, 1, tzinfo=timezone.utc)
WINDOW_END = datetime(2025, 6, 1, tzinfo=timezone.utc)
REGIONS = ("north", "south", "east", "west")

MAX_FAILURES = 25         # per request: transport errors, 5xx, unreadable bodies
MAX_TOKEN_REFRESHES = 10  # per request: consecutive 401s

stats = Counter()
log = None


def note(message):
    log.write(f"{time.strftime('%H:%M:%S')} {message}\n")
    log.flush()


def retry_after_seconds(headers):
    value = headers.get("Retry-After")
    if value is None:
        return None
    try:
        return max(0.0, float(value))
    except ValueError:  # HTTP-date form
        when = email.utils.parsedate_to_datetime(value)
        return max(0.0, (when - datetime.now(timezone.utc)).total_seconds())


class Api:
    def __init__(self):
        self.token = None

    def _send(self, method, path, auth):
        headers = {"Authorization": f"Bearer {self.token}"} if auth else {}
        req = urllib.request.Request(BASE + path, method=method, headers=headers)
        stats["requests"] += 1
        try:
            with urllib.request.urlopen(req, timeout=30) as resp:
                return resp.status, resp.headers, resp.read().decode("utf-8")
        except urllib.error.HTTPError as err:
            return err.code, err.headers, err.read().decode("utf-8", "replace")

    def request(self, method, path, auth=True):
        """Return (status, body) for HTTP 200 and 404. Waits out rate limits, replaces a rejected
        token, and repeats transient failures. Any other response raises so it can be inspected."""
        failures = refreshes = 0
        while True:
            if auth and self.token is None:
                self.new_token()
            try:
                status, headers, text = self._send(method, path, auth)
            except OSError as exc:  # refused, reset or timed out
                status, headers, text = None, {}, repr(exc)

            if status == 200:
                try:
                    return status, json.loads(text)
                except ValueError:
                    status, text = None, f"unreadable body: {text[:200]!r}"

            if status == 404:
                return status, None

            if status == 401 and auth:
                refreshes += 1
                stats["token_rejected"] += 1
                if refreshes > MAX_TOKEN_REFRESHES:
                    raise RuntimeError(f"token rejected {refreshes} times on {path}")
                note(f"401 on {path}: fetching a new token")
                self.token = None
                continue

            if status == 429:
                wait = retry_after_seconds(headers)
                if wait is None:
                    raise RuntimeError(f"429 with no Retry-After on {path}: {text[:300]!r}")
                stats["rate_limited"] += 1
                note(f"429 on {path}: waiting {wait:.2f}s as instructed")
                time.sleep(wait + 0.05)
                continue

            if status is None or status >= 500:
                failures += 1
                stats["repeated_after_failure"] += 1
                if failures > MAX_FAILURES:
                    raise RuntimeError(f"gave up on {path} after {failures} failures: {status} {text[:300]!r}")
                wait = retry_after_seconds(headers)
                delay = wait if wait is not None else min(30.0, 0.5 * 2 ** failures)
                note(f"{status} on {path}: {text[:150]!r}; repeating in {delay:.2f}s")
                time.sleep(delay)
                continue

            raise RuntimeError(f"unexpected HTTP {status} on {path}: {text[:300]!r}")

    def new_token(self):
        status, body = self.request("POST", "/token", auth=False)
        if status != 200:
            raise RuntimeError(f"token request returned {status}")
        self.token = body["token"]
        stats["tokens_fetched"] += 1


def list_orders(api):
    items, path, page_no, total_pages = [], "/orders?page=1", 1, None
    while path is not None:
        status, body = api.request("GET", path)
        if status != 200:
            raise RuntimeError(f"{path}: HTTP {status}")
        if body["page"] != page_no:
            raise RuntimeError(f"asked for page {page_no}, got page {body['page']}")
        if total_pages is None:
            total_pages = body["total_pages"]
        if page_no > total_pages:
            raise RuntimeError(f"listing runs past total_pages={total_pages}")
        (RAW_DIR / f"orders-page-{page_no:03d}.json").write_text(json.dumps(body))
        items.extend(body["items"])
        stats["pages"] += 1
        expected_next = f"/orders?page={page_no + 1}" if page_no < total_pages else None
        if body["next"] != expected_next:
            raise RuntimeError(f"page {page_no}: next is {body['next']!r}, expected {expected_next!r}")
        path = body["next"]
        page_no += 1
    if page_no - 1 != total_pages:
        raise RuntimeError(f"read {page_no - 1} pages, service reports {total_pages}")
    return items


