    if customer_id not in cache:
        status, body = api.request("GET", f"/customers/{customer_id}")
        if status != 200:
            raise RuntimeError(f"customer {customer_id}: HTTP {status}")
        pct = body["discount_pct"]
        if body["id"] != customer_id or body["region"] not in REGIONS or type(pct) is not int or not 0 <= pct <= 100:
            raise RuntimeError(f"unexpected customer record: {body}")
        cache[customer_id] = body
        stats["customer_lookups"] += 1
    return cache[customer_id]


