    when = datetime.fromisoformat(placed_at)
    if when.tzinfo is None:
        raise RuntimeError(f"placed_at has no offset: {placed_at!r}")
    return when.astimezone(timezone.utc)


def discounted_cents(amount_cents, discount_pct):
    """amount * (100 - pct) / 100, rounded half up to a whole cent, in integers so there is no float error."""
    quotient, remainder = divmod(amount_cents * (100 - discount_pct), 100)
    return quotient + 1 if remainder * 2 >= 100 else quotient


def run():
    api = Api()
    listed = list_orders(api)

    first_seen, duplicates, conflicts = {}, 0, 0
    for item in listed:
        if item["id"] in first_seen:
            duplicates += 1
            if first_seen[item["id"]] != item:
                conflicts += 1
        else:
            first_seen[item["id"]] = item
    if conflicts:
        raise RuntimeError(f"{conflicts} repeated listings differ from the first copy")

    statuses, cache = Counter(), {}
    total = count = 0
    by_region = {region: 0 for region in REGIONS}
    for order in first_seen.values():
        statuses[order["status"]] += 1
        amount = order["amount_cents"]
        if type(amount) is not int or amount < 0:
            raise RuntimeError(f"bad amount_cents on {order['id']}: {amount!r}")
        placed = parse_utc(order["placed_at"])
        if order["status"] != "shipped":
            continue
        if not WINDOW_START <= placed < WINDOW_END:
            continue
        cust = customer(api, order["customer_id"], cache)
        due = discounted_cents(amount, cust["discount_pct"])
        by_region[cust["region"]] += due
        total += due
        count += 1

    (RAW_DIR / "customers.json").write_text(json.dumps(cache))
    print(f"listed {len(listed)} items, {len(first_seen)} distinct orders, {duplicates} repeated listings")
    print(f"statuses: {dict(statuses)}")
    print(f"qualifying orders: {count}; customers looked up: {len(cache)}")
    print(f"total_cents={total} by_region={by_region}")
    print(f"stats: {dict(stats)}")

    result = {
        "total_cents": total,
        "order_count": count,
        "duplicates_skipped": duplicates,
        "by_region": by_region,
    }
    if sum(by_region.values()) != total:
        raise RuntimeError("by_region does not add up to total_cents")
    RESULT_PATH.write_text(json.dumps(result, indent=2) + "\n")
    print(RESULT_PATH.read_text())


def main():
    global log
    WORKDIR.mkdir(parents=True, exist_ok=True)
    RAW_DIR.mkdir(parents=True, exist_ok=True)
    log = open(LOG_PATH, "w")
    run()


if __name__ == "__main__":
    main()

